CREATE VIEW vw_game_seed_similarity AS WITH library_size AS (SELECT count_star() AS game_count FROM DimGame), classification_frequency AS (SELECT bgc.ClassificationKey, count(DISTINCT bgc.GameKey) AS games_with_classification FROM BridgeGameClassification AS bgc GROUP BY bgc.ClassificationKey), classification_weight AS (SELECT cf.ClassificationKey, (ln(((ls.game_count + 1.0) / (cf.games_with_classification + 1.0))) + 1.0) AS feature_weight FROM classification_frequency AS cf , library_size AS ls), game_weight AS (SELECT bgc.GameKey, sum(cw.feature_weight) AS total_feature_weight FROM BridgeGameClassification AS bgc INNER JOIN classification_weight AS cw ON ((cw.ClassificationKey = bgc.ClassificationKey)) GROUP BY bgc.GameKey), seed_games AS (SELECT psg.PreferenceSeedID, psg.PreferenceTier, psg.ConditionalFlag, dg.GameKey AS SeedGameKey, dg.GameID AS SeedGameID, dg.GameTitle AS SeedGameTitle FROM PreferenceSeedGame AS psg INNER JOIN DimGame AS dg ON ((dg.GameID = psg.GameID))), seed_weight AS (SELECT sg.PreferenceSeedID, sum(cw.feature_weight) AS total_feature_weight FROM seed_games AS sg INNER JOIN BridgeGameClassification AS bgc ON ((bgc.GameKey = sg.SeedGameKey)) INNER JOIN classification_weight AS cw ON ((cw.ClassificationKey = bgc.ClassificationKey)) GROUP BY sg.PreferenceSeedID), intersection_weight AS (SELECT g.GameKey, sg.PreferenceSeedID, sum(cw.feature_weight) AS shared_feature_weight FROM DimGame AS g , seed_games AS sg INNER JOIN BridgeGameClassification AS game_class ON ((game_class.GameKey = g.GameKey)) INNER JOIN BridgeGameClassification AS seed_class ON (((seed_class.GameKey = sg.SeedGameKey) AND (seed_class.ClassificationKey = game_class.ClassificationKey))) INNER JOIN classification_weight AS cw ON ((cw.ClassificationKey = game_class.ClassificationKey)) GROUP BY g.GameKey, sg.PreferenceSeedID), all_pairs AS (SELECT g.GameKey, g.GameID, g.GameTitle, sg.PreferenceSeedID, sg.PreferenceTier, sg.ConditionalFlag, sg.SeedGameKey, sg.SeedGameID, sg.SeedGameTitle FROM DimGame AS g , seed_games AS sg)SELECT ap.GameKey, ap.GameID, ap.GameTitle, ap.PreferenceSeedID, ap.PreferenceTier, ap.ConditionalFlag, ap.SeedGameKey, ap.SeedGameID, ap.SeedGameTitle, COALESCE(iw.shared_feature_weight, 0) AS shared_feature_weight, gw.total_feature_weight AS game_feature_weight, sw.total_feature_weight AS seed_feature_weight, round(((100.0 * COALESCE(iw.shared_feature_weight, 0)) / "nullif"(((gw.total_feature_weight + sw.total_feature_weight) - COALESCE(iw.shared_feature_weight, 0)), 0)), 2) AS similarity_pct FROM all_pairs AS ap LEFT JOIN game_weight AS gw ON ((gw.GameKey = ap.GameKey)) LEFT JOIN seed_weight AS sw ON ((sw.PreferenceSeedID = ap.PreferenceSeedID)) LEFT JOIN intersection_weight AS iw ON (((iw.GameKey = ap.GameKey) AND (iw.PreferenceSeedID = ap.PreferenceSeedID)));
